import{z as o,x as p,o as e,c as i,q as A,j as l,D as a,d as r,s as t,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"预训练配方收束","description":"","frontmatter":{"title":"预训练配方收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-map.md","filePath":"llm/pf2-map.md","lastUpdated":1791413859000}'),s={name:"llm/pf2-map.md"};function D(m,E,d,f,h,c){const B=p("Mermaid");return e(),i("div",null,[E[2]||(E[2]=A('<h1 id="预训练配方收束" tabindex="-1">预训练配方收束 <a class="header-anchor" href="#预训练配方收束" aria-label="Permalink to &quot;预训练配方收束&quot;">​</a></h1><div class="epigraph"><p>配方的剩余物不是超参数字，而是判据：换一代硬件、换一套数据，数字全部过时，判据仍在。</p><footer>—— 据本课程十六课整理</footer></div><p><a href="/llm/pf2-repro-recipe-mgmt">上一课</a>把配方存档成复现包，十六课到此齐了。本课不添新内容，像所有收束课一样做减法：把三次点火之间的决策收成一张总图、几条不变量与一排高频拦错事，让细节退场之后，配方还能被交接、被审计、被下一次开工复用。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>为什么要收束：十六课的细节——coord check 怎么做、插值衔接怎么平滑、留出集怎么分层——都会随工具与规模换代，但配方事故的类型不会。收束课把每类事故倒推回它该被拦住的那一课：配比失控是开工前判据没写、尖峰失控是预案没建、选点失控是门禁没预注册——病根同构：某个决策点没有判据就放行了。收束之后，检查一张配方是否健康，不再需要读完十六课，只需要对这张图问几个问题。</p><p><span class="marginnote">「判据」就是先于观测写下的验收标准：什么算过、什么算不过、平手怎么算。它与「事后解释」的分界在签字时机——判据在看数据之前定死，看完了再给的说法一律不算数。</span></p><h3 id="一张总图" tabindex="-1">一张总图 <a class="header-anchor" href="#一张总图" aria-label="Permalink to &quot;一张总图&quot;">​</a></h3><p>开工前三课定地基：<a href="/llm/pf2-pretrain-checklist">检查清单</a>把六项写成启动判据，<a href="/llm/pf2-data-mix-final">配比定稿</a>把梯度预算分到桶并留证据链，<a href="/llm/pf2-hparam-scaling-rules">缩放规则</a>用原点、标度、校验三部件把超参从代理搬到目标。训练中五课管过程：<a href="/llm/pf2-lr-warmup-practice">日程契约</a>与<a href="/llm/pf2-regularization-dropout">正则取舍</a>定旋钮初值，<a href="/llm/pf2-longrun-health">健康管理</a>与<a href="/llm/pf2-midtrain-eval-gates">中途门禁</a>守过程，<a href="/llm/pf2-data-exhaustion">数据耗尽</a>给计划外缺口留合法通道。收束八课管交付与反思：<a href="/llm/pf2-annealing-curriculum">退火</a>、<a href="/llm/pf2-checkpoint-selection">选点</a>、<a href="/llm/pf2-model-eval-gates">发布门禁</a>走完交付链，<a href="/llm/pf2-scaling-failures">缩放失败</a>与<a href="/llm/pf2-compute-accounting">算力账</a>复盘规划，<a href="/llm/pf2-opensource-recipes">开源对照</a>与<a href="/llm/pf2-repro-recipe-mgmt">复现包</a>对外与对后。</p>',8)),(e(),l(n,null,{default:a(()=>[t(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20PRE%5B%22%E5%BC%80%E5%B7%A5%E5%89%8D%22%5D%0A%20%20%20%20A%5B%22%E6%A3%80%E6%9F%A5%E6%B8%85%E5%8D%95%EF%BC%9A%E5%85%AD%E9%A1%B9%E5%88%A4%E6%8D%AE%22%5D%20--%3E%20B%5B%22%E9%85%8D%E6%AF%94%E5%AE%9A%E7%A8%BF%EF%BC%9A%E6%A1%B6%20%2B%20%E8%AF%81%E6%8D%AE%E9%93%BE%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E7%BC%A9%E6%94%BE%E8%A7%84%E5%88%99%EF%BC%9A%E5%8E%9F%E7%82%B9%20%2B%20%E6%A0%87%E5%BA%A6%20%2B%20%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20end%0A%20%20subgraph%20MID%5B%22%E8%AE%AD%E7%BB%83%E4%B8%AD%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E6%97%A5%E7%A8%8B%E5%A5%91%E7%BA%A6%20%2B%20%E6%AD%A3%E5%88%99%E5%8F%96%E8%88%8D%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E5%81%A5%E5%BA%B7%E7%AE%A1%E7%90%86%20%2B%20%E4%B8%AD%E9%80%94%E9%97%A8%E7%A6%81%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22%E6%95%B0%E6%8D%AE%E8%80%97%E5%B0%BD%E7%9A%84%E5%90%88%E6%B3%95%E9%80%9A%E9%81%93%22%5D%0A%20%20end%0A%20%20subgraph%20END%5B%22%E6%94%B6%E6%9D%9F%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E9%80%80%E7%81%AB%EF%BC%9A%E5%8F%8C%E8%BD%B4%E9%98%B6%E6%AE%B5%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%E9%80%89%E7%82%B9%20%2B%20%E5%8F%91%E5%B8%83%E9%97%A8%E7%A6%81%22%5D%0A%20%20%20%20H%20--%3E%20I%5B%22%E5%A4%B1%E8%B4%A5%E6%B8%85%E5%8D%95%20%2B%20%E7%AE%97%E5%8A%9B%E8%B4%A6%22%5D%0A%20%20%20%20I%20--%3E%20J%5B%22%E5%BC%80%E6%BA%90%E5%AF%B9%E7%85%A7%20%2B%20%E5%A4%8D%E7%8E%B0%E5%8C%85%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条不变量横贯十六课。其一，<strong>判据先行</strong>：任何决策——点火、调整、选点、发布——的判据写在观测之前；事后解释不是判据。其二，<strong>口径同源</strong>：token、FLOPs、卡时、钱四层记账同一来源；配比的桶、日志的曲线、报告的分数引用同一套指纹，三处不一致则一切对比作废。其三，<strong>旋钮可指认</strong>：任何中途动作都能说出动的是哪一课的哪个旋钮、走了哪条合法通道；说不出指认的动作都算事故。高频拦错事七件：检查单没判据、先配比后清洗、代理结论越界直搬、尖峰当噪声不归档、用测试榜选点、把 20 当常数写进脚本、复现包只有权重。七件各占一课的份量，收束时并成一排。</p><p><span class="marginnote">对账的硬指标与设施课同构：拿最近一次废掉的点火回放，能否在十分钟内指出它违反哪条不变量、该在十六课的哪一课被拦住——指不出来，说明配方没有真的在管。</span></p><p><span class="marginnote">直觉类比：三条不变量像工厂的「流程留痕」制度——判据先行是先定验收标准再生产，口径同源是所有报表共用同一套底账，旋钮可指认是每次改动都有签字人；缺任何一条，复盘都会变成罗生门。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么按「总图、不变量、拦错事」收而不是按单元复述：十五课的依赖顺序就是故障的传播路径——开工判据缺一项，训练中的每个观测都失去对照；口径不同源，收束时的一切复盘都在流沙上。对账因此从后往前问：复现包为什么走不通谱系、发布门禁为什么临时改判据、中途门禁为什么变成看分数猜趋势——每一步都能指回前一步的欠账，配方才算闭环。这也回答了这门课与「训练基础设施」课程的分工：那边管骨架与账本，这边管决策与判据；两条线在复现包里会合——骨架记账户，判据记决策，缺一条，另一条都不可信。</p><p><span class="marginnote">常见误区：初学者容易把收束课当成「划重点背数字」。恰恰相反——数字的半衰期最短，换一代硬件就过时；真正能带走的是判据：哪些决策点必须在观测前定标准，事故该倒推回哪一课去拦。</span></p>',7)),(e(),l(n,null,{default:a(()=>[t(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%A4%8D%E7%8E%B0%E5%8C%85%E8%B5%B0%E4%B8%8D%E9%80%9A%E8%B0%B1%E7%B3%BB%EF%BC%9F%22%5D%20--%3E%7C%E5%80%92%E6%8E%A8%7C%20B%5B%22%E5%8F%91%E5%B8%83%E9%97%A8%E7%A6%81%E4%B8%BA%E4%BD%95%E4%B8%B4%E6%97%B6%E6%94%B9%E5%88%A4%E6%8D%AE%EF%BC%9F%22%5D%0A%20%20B%20--%3E%7C%E5%80%92%E6%8E%A8%7C%20C%5B%22%E4%B8%AD%E9%80%94%E9%97%A8%E7%A6%81%E4%B8%BA%E4%BD%95%E5%8F%98%E6%88%90%E7%9C%8B%E5%88%86%E6%95%B0%E7%8C%9C%E8%B6%8B%E5%8A%BF%EF%BC%9F%22%5D%0A%20%20C%20--%3E%7C%E5%80%92%E6%8E%A8%7C%20D%5B%22%E5%BC%80%E5%B7%A5%E5%88%A4%E6%8D%AE%E6%98%AF%E5%90%A6%E7%BC%BA%E9%A1%B9%EF%BC%9F%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%AF%8F%E4%B8%80%E6%AD%A5%E6%8C%87%E5%9B%9E%E5%89%8D%E4%B8%80%E6%AD%A5%E7%9A%84%E6%AC%A0%E8%B4%A6%22%5D%0A%20%20E%20--%3E%20F%7B%22%E8%83%BD%E5%90%A6%E9%97%AD%E7%8E%AF%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%E8%83%BD%7C%20G%5B%22%E9%85%8D%E6%96%B9%E7%9C%9F%E7%9A%84%E5%9C%A8%E7%AE%A1%22%5D%0A%20%20F%20--%3E%7C%E4%B8%8D%E8%83%BD%7C%20H%5B%22%E6%89%BE%E5%88%B0%E7%97%85%E6%A0%B9%E8%AF%BE%EF%BC%8C%E8%A1%A5%E5%88%A4%E6%8D%AE%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p>这张图回答的是「对账怎么从后往前走」：从最末端的复现包开始逐级倒推，每一环都能指认前一环的欠账，闭环才算成立。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程管预训练段的配方决策，不管后训练的配方结构——RM、SFT、RL 各自成课；推理与服务的成本账在服务课程。设施层（骨架、检查点、调度、跟踪）整体在「训练基础设施」，本课只消费其判据。配方数值的半衰期最短：词表、稳定件与优化器的换代都会重画敏感度谷；课程钉住的是判据先行、口径同源、旋钮可指认这三层不变量。对下一次开工，交接物就是上一课的复现包加这一课的三条不变量——数字从新拟合，判据照旧执行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>十六课收成一张图：开工前三课定地基，训练中五课守过程，收束八课管交付与复盘。</li><li>三条不变量：判据先行、口径同源、旋钮可指认。</li><li>七件高频拦错事：无判据清单、先比后洗、越界迁移、尖峰不归档、测试榜选点、常数化系数、权重式复现包。</li><li>与基础设施课程的分工：那边管骨架与账本，这边管决策与判据，在复现包会合。</li><li>出处：按本课程十六课整理；数量级与口径见各课出处行。</li></ul>',5))])}const F=o(s,[["render",D]]);export{u as __pageData,F as default};
